import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Deposits & Withdrawals","description":"","frontmatter":{},"headers":[],"relativePath":"guide/finance.md","filePath":"guide/finance.md","lastUpdated":1790683574000}'),o={name:"guide/finance.md"};function r(i,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="deposits-withdrawals" tabindex="-1">Deposits &amp; Withdrawals <a class="header-anchor" href="#deposits-withdrawals" aria-label="Permalink to &quot;Deposits &amp; Withdrawals&quot;">​</a></h1><h2 id="deposits" tabindex="-1">Deposits <a class="header-anchor" href="#deposits" aria-label="Permalink to &quot;Deposits&quot;">​</a></h2><p>The platform supports two digital asset deposit channels, switchable with one click in the admin console. <strong>Only one is active at a time.</strong></p><h3 id="user-flow" tabindex="-1">User flow <a class="header-anchor" href="#user-flow" aria-label="Permalink to &quot;User flow&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User opens the deposit page</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Selects coin and network (TRC20 / ERC20 / BEP20, etc.)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Gets a dedicated receiving address (stable per user; no need to request again for repeat deposits)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>User transfers funds</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Credited automatically after on-chain confirmation</span></span></code></pre></div><h3 id="how-the-two-channels-differ" tabindex="-1">How the two channels differ <a class="header-anchor" href="#how-the-two-channels-differ" aria-label="Permalink to &quot;How the two channels differ&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>UDUN channel</th><th>TokenPay channel</th></tr></thead><tbody><tr><td>User action</td><td>Opens the deposit page and sees their dedicated address; whatever they send is credited</td><td><strong>Order-based</strong>: enter an amount first; the system generates the coin amount due, a payment QR code and a countdown, and the user pays that amount</td></tr><tr><td>Receiving address</td><td>Dedicated per user, long-term stable</td><td>Dedicated per user, long-term stable</td></tr><tr><td>Credited based on</td><td>Amount actually received on-chain</td><td>The <strong>on-chain received amount</strong> in the callback; if it differs from the entered amount, the received amount wins</td></tr><tr><td>Best for</td><td>Users used to free-form transfers</td><td>Scenarios needing &quot;pay exactly what you see&quot; and fewer wrong-amount deposits</td></tr></tbody></table><p>Users see the same &quot;Deposit&quot; entry for both channels and do not need to know which one is behind it; operators choose one under &quot;Third-Party Configuration → Payment gateway&quot;, and it takes effect the next time a user opens the deposit page.</p><div class="warning custom-block"><p class="custom-block-title">Configure TokenPay before switching to it</p><p>The service URL, ApiToken and callback URL in the &quot;TokenPay&quot; card must be filled in and enabled before switching the payment gateway. If the callback URL is wrong or missing, orders stay &quot;Under review&quot; after users pay and never get credited. Both cards are <strong>super-admin only</strong>; see <a href="/CoinExchange/guide/site-config#third-party">Third-party configuration</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">Automatic crediting</p><p>Deposits are credited automatically based on the <strong>amount actually received on-chain</strong>, with no manual review. The &quot;Deposit Records&quot; page in the admin console is for lookup and reconciliation; normally operators do not need to confirm anything by hand.</p></div><h3 id="what-operators-do" tabindex="-1">What operators do <a class="header-anchor" href="#what-operators-do" aria-label="Permalink to &quot;What operators do&quot;">​</a></h3><ul><li>Configure which coins and networks are open under &quot;Deposit Channels&quot;</li><li>Look up deposits and handle user inquiries under &quot;Deposit Records&quot;</li><li>Switch to the backup channel when a channel fails</li><li>In rare cases (e.g. a delayed channel callback) an order stays &quot;Under review&quot;; after checking the on-chain receipt, you can approve it manually under &quot;Deposit Management&quot;. Normal deposits <strong>do not</strong> need operator confirmation</li></ul><div class="warning custom-block"><p class="custom-block-title">Match networks correctly</p><p>The mapping between coins and networks (chains) must be configured correctly. A wrong mapping leads users to transfer on the wrong chain, and <strong>such assets usually cannot be recovered</strong>.</p></div><h2 id="withdrawals" tabindex="-1">Withdrawals <a class="header-anchor" href="#withdrawals" aria-label="Permalink to &quot;Withdrawals&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User submits a withdrawal request</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>System checks: KYC level, withdrawal limit, fund password</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>A pending record appears under &quot;Withdrawal Management&quot;</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Operator reviews → approve (on-chain transfer sent) / reject (refunded to the account)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Status updates on the user side</span></span></code></pre></div><h3 id="key-points-for-operators" tabindex="-1">Key points for operators <a class="header-anchor" href="#key-points-for-operators" aria-label="Permalink to &quot;Key points for operators&quot;">​</a></h3><ul><li><strong>Withdrawal channel</strong> configuration decides which coins and networks are open</li><li><strong>KYC limits</strong> decide the withdrawal limits for each verification level</li><li>A rejected withdrawal returns the frozen assets to the user&#39;s account</li></ul><div class="danger custom-block"><p class="custom-block-title">Approval is irreversible</p><p>Approving a withdrawal sends a real on-chain transfer, which <strong>cannot be recalled once sent</strong>. When reviewing, check each of the following:</p><ol><li>Does the withdrawal address match the selected network?</li><li>Is the user&#39;s account in an abnormal state?</li><li>Is the amount consistent with the user&#39;s assets and ledger? (Manually double-check unusually large amounts)</li></ol></div><h2 id="fund-sweeping" tabindex="-1">Fund sweeping <a class="header-anchor" href="#fund-sweeping" aria-label="Permalink to &quot;Fund sweeping&quot;">​</a></h2><p>Deposited funds received by the platform are swept to a unified address. Sweep records are available in the admin console.</p><h2 id="ledger" tabindex="-1">Ledger <a class="header-anchor" href="#ledger" aria-label="Permalink to &quot;Ledger&quot;">​</a></h2><p>Every movement of funds (deposits, withdrawals, transfers, orders, settlements, campaign rewards, manual adjustments) creates a ledger entry recording:</p><ul><li>Type of change</li><li>Amount changed</li><li><strong>Balance before / balance after</strong></li><li>Time</li></ul><p>The ledger is the source of truth for reconciliation. For any &quot;balance doesn&#39;t add up&quot; issue, the first step is to pull that user&#39;s complete ledger and check it entry by entry.</p>`,24)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
